import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const o="/llamatron/assets/track_editor.7AJ-oF8o.svg",k=JSON.parse('{"title":"Tracks","description":"","frontmatter":{},"headers":[],"relativePath":"TRACKS.md","filePath":"TRACKS.md"}'),n={name:"TRACKS.md"};function c(d,e,i,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="tracks" tabindex="-1">Tracks <a class="header-anchor" href="#tracks" aria-label="Permalink to &quot;Tracks&quot;">​</a></h1><p>A track is a column of Arrange, with its own instrument, transpose, CC numbers and more. This page covers the track editor, whose settings apply to every clip on the track.</p><p><img src="'+o+'" alt="A track&#39;s settings"></p><h2 id="track-settings" tabindex="-1">Track Settings <a class="header-anchor" href="#track-settings" aria-label="Permalink to &quot;Track Settings&quot;">​</a></h2><p>On Arrange, <code>ENTER</code> on a track&#39;s name opens the track editor. Tracks become tracks in Live in the order Arrange shows them.</p><p>Under the Name, a box of tabs holds the rest, as on the clip page (see <a href="./CLIPS#clip-settings">Clips</a> for the keys): Settings, with Routing (Instrument, Kind, Mute, Groove) and Notes (Transpose, the octaves, Default velocity, Accent, Velocity); MIDI CCs; then the generators in the order they run: Chords, Arp, Guitarify, Timing and Phrasing, the track&#39;s built-in generators, and last More Generators, the Generators field, whose generators run after every built-in. A track&#39;s built-in generator plays on every clip of the track whose own of the same kind is off; its tab names the clips whose own stands in for it, such as <code>chords overridden in 1 clip: verse (lead)</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>ENTER</code> renames the track, updating every scene and every clip that grabs from the track. The pattern group of the track&#39;s name is renamed too, unless a group already has the new name.</td></tr><tr><td>Kind</td><td><code>Drum</code> or <code>Melodic</code>, set when the track is made on Arrange by the <code>+</code> it was added from, and never changed. A drum track is never transposed.</td></tr><tr><td>Mute</td><td>Starts the track switched off in Live, shown with <code>●</code>, so the track is silent until switched on. A muted track&#39;s clips are still written, so the track can be switched on to hear them, and other tracks can still grab notes from it. Mute is meant for tracks that only feed grabs or a hocket. <code>Space</code> or <code>ENTER</code> toggles it.</td></tr><tr><td>Groove</td><td>A groove for the track&#39;s clips in place of the scene&#39;s or the song&#39;s, or <code>off</code> to play them straight whatever the scene and song choose, which keeps a kick straight in a swung song. <code>[</code> and <code>]</code> step through the choices, <code>ENTER</code> picks from a list, and <code>Bksp</code> goes back to the scene&#39;s or the song&#39;s. See <a href="./GROOVES">Grooves</a>.</td></tr><tr><td>Transpose</td><td>Moves every note on the track along the scale, from -24 to 24, without changing its patterns; in a seven-note scale, 7 is an octave. Drum patterns are never transposed, on any track.</td></tr><tr><td>Lowest octave, Highest octave</td><td>The octaves the track&#39;s instrument plays, in the File/Global page&#39;s octave labels, the whole MIDI range at first. The piano roll marks the rows outside them when this track alone plays a pattern. <code>[</code> and <code>]</code> move an end, which can&#39;t cross the other, <code>ENTER</code> types one, and <code>Bksp</code> puts it back at the end of the range.</td></tr><tr><td>Default velocity</td><td>The velocity a step with none typed plays at on the track, 1 to 127. Until set, the field shows the value of the track&#39;s instrument, such as <code>80 (from instrument)</code>, and a track with no instrument plays at 127. <code>Bksp</code> gives the field back to the instrument.</td></tr><tr><td>Velocity</td><td>How loud every clip of the track plays, as a percentage, from 0% to 200%, 100% unless set. It stacks with the instrument&#39;s, the scene&#39;s and the clip&#39;s, each scaling the others, so a quiet pad track at 70% stays quieter in every scene. See <a href="./SCENES#velocity-and-velocity-ramps">Velocity and Velocity Ramps</a>.</td></tr><tr><td>Accent</td><td>What a step with its Accent on adds to its velocity on the track, 0 to 127, <code>+15</code> unless set, on top of the Accent of the track&#39;s instrument. A drummer&#39;s accents and a singer&#39;s stressed notes are entered as switches on the pattern&#39;s Accent row, which is quicker than typing velocities, and the same pattern is accented more or less on another track.</td></tr><tr><td>Generators</td><td>On the More Generators tab: the generators every clip on the track runs, after the clip&#39;s own and the scene&#39;s, edited as a clip&#39;s are. A track&#39;s generators give a whole part the same treatment, such as a strum or a slight drift; a generator named both here and on a clip runs twice. See <a href="./GENERATORS">Generators</a>.</td></tr><tr><td>Instrument</td><td>The instrument the track plays through in real time, chosen from the instruments of its kind on the Instruments page; a track made on Arrange starts with an instrument of its own, named after it. <code>ENTER</code> chooses another; an instrument is changed, never taken away. A track of an older set saved without one shows <code>(none)</code> until one is chosen. See <a href="./INSTRUMENTS">Instruments</a>.</td></tr><tr><td>CC 1 to CC 4</td><td>The CC number each of a pattern&#39;s CC rows sends on this track, from 0 to 127. <code>Bksp</code> sets none, so that the row sends nothing on this track. CC 1 is usually the mod wheel, and CC 74 the filter cutoff.</td></tr></tbody></table>',7)])])}const u=t(n,[["render",c]]);export{k as __pageData,u as default};
